use wowdps_model::ItemKind;

/// The kind of item a spell comes from, or `None` for a spell no item grants.
pub(crate) fn item_kind(spell_id: u32) -> Option<ItemKind> {
    let i = TABLE.binary_search_by_key(&spell_id, |e| e.0).ok()?;
    let &(_, code) = TABLE.get(i)?;
    KINDS.get(code as usize).copied()
}

/// R26: the one trinket a spell comes from — (item id, the item's name)
/// — or `None` for a spell no single trinket grants: the ability tree
/// nests a proc's damage under the trinket that fired it.
pub(crate) fn trinket_of(spell_id: u32) -> Option<(u32, &'static str)> {
    let i = TRINKETS.binary_search_by_key(&spell_id, |e| e.0).ok()?;
    let &(_, item, name) = TRINKETS.get(i)?;
    Some((item, NAMES.get(name as usize).copied()?))
}

